SELECT setval(pg_get_serial_sequence('lanops.verificaciones', 'id'), (SELECT max(id) FROM lanops.verificaciones));

SELECT (SELECT count(*) FROM lanops.configuracion) AS configuracion, (SELECT count(*) FROM lanops.entidades) AS entidades, (SELECT count(*) FROM lanops.habilidades) AS habilidades, (SELECT count(*) FROM lanops.evaluadores) AS evaluadores, (SELECT count(*) FROM lanops.usuarios) AS usuarios, (SELECT count(*) FROM lanops.usuario_habilidad) AS usuario_habilidad, (SELECT count(*) FROM lanops.preferencias) AS preferencias, (SELECT count(*) FROM lanops.verificaciones) AS verificaciones;
